package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.JsonGenerationException;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.core.io.CharacterEscapes;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;

/**
 * Unit tests for JsonGenerator.writeEmbeddedObject
 */
public class JsonGenerator_writeEmbeddedObject_TriageGen1Test {

    private JsonGenerator jsonGenerator;

    @Before
    public void setUp() {
        // JsonGenerator is abstract, so we mock it to test the concrete logic in the method
        // Note: In a real Jackson environment, this method is part of the base class
        // and we would use a concrete implementation like JsonGeneratorImpl.
        // Since we are testing the provided snippet, we mock the abstract class.
        jsonGenerator = mock(JsonGenerator.class, Mockito.withSettings().useConstructor().defaultAnswer(Mockito.CALLS_REAL_METHODS));
    }

    @Test
    public void testWriteEmbeddedObject_WithNull_ShouldDoNothing() throws IOException {
        jsonGenerator.writeEmbeddedObject(null);

        // Verify no interactions with writeBinary or other methods
        verifyNoInteractions(jsonGenerator);
    }

    @Test
    public void testWriteEmbeddedObject_WithByteArray_ShouldCallWriteBinary() throws IOException {
        byte[] data = new byte[]{0x01, 0x02, 0x03};

        // We need to ensure writeBinary is actually called on the mock
        jsonGenerator.writeEmbeddedObject(data);

        verify(jsonGenerator).writeBinary(data);
    }

    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_WithUnsupportedType_ShouldThrowException() throws IOException {
        Object unsupportedObject = "I am a string, not a byte array";

        jsonGenerator.writeEmbeddedObject(unsupportedObject);
    }

    @Test
    public void testWriteEmbeddedObject_WithUnsupportedType_ExceptionMessageContainsClassName() throws IOException {
        Object unsupportedObject = 12345; // Integer

        try {
            jsonGenerator.writeEmbeddedObject(unsupportedObject);
        } catch (JsonGenerationException e) {
            String message = e.getMessage();
            assert message.contains("No native support for writing embedded objects of type");
            assert message.contains("java.lang.Integer");
        }
    }

    @Test
    public void testWriteEmbeddedObject_WithByteArray_WhenWriteBinaryThrowsIOException_ShouldPropagate() throws IOException {
        byte[] data = new byte[]{0x01};
        doThrow(new IOException("Disk full")).when(jsonGenerator).writeBinary(any(byte[].class));

        try {
            jsonGenerator.writeEmbeddedObject(data);
            org.junit.Assert.fail("Expected IOException to be thrown");
        } catch (IOException e) {
            org.junit.Assert.assertEquals("Disk full", e.getMessage());
        }
    }
}
